configuration.script:
var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

var ok = (items["HumiSetpoint"] != NULL && items["HumiSetpoint"] != UNDEF &&
          items["MyHumiProxy"] != NULL && items["MyHumiProxy"] != UNDEF);

if(!ok){
  logError("humidifier", "Cannot determine humidifier/dehumidifier state, HumiSetpoint = " + items["HumiSetpoint"] + " and MyHumiProxy = " + items["MyHumiProxy"]);
}

(ok);

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

// negative delta means humidity is higher than the setpoint
var delta = items["HumiSetpoint"].floatValue() - items["MyHumiProxy"].floatValue();

// TODO: add hysteresis
var cmd = OFF
if((items["HumidityType"] == "Humidify" && delta > 0) ||
   (items["HumidityType"] == "Dehumidify" && delta < 0) ||
   items["HumidityMode"] == "Boost") {
  cmd = ON;
}

events.sendCommand("HumidityCtrl", cmd);

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

logInfo("backup", "Backup complete!");
events.postUpdate("BackupButton", "Backup complete!");
events.sendCommand("BackupTimestampCommand", "ON"); // gets the latest timestamp

createTimerSecs(5, function(){ events.postUpdate("BackupButton", ""); });

var ok = true;

// If the all the relay states match the calls, we abort this rule
if(items["HeatingPin"] == command) {  // heating pin matches what is being asked for
  // if stage 2 is also off and the relay matches, we know we can skip this rule
  if(items["Heating2"] == OFF) {
    if(items["Heating2Pin"] == OFF) {
      ok = false; // 2nd stage is off, and relay matches 
    }
  } else { 
    // 2nd stage heat is on. We have to run the rule to determine if the
    // temperature has risen enough that we want to turn off stage2, or fallen
    // enough so we need to turn on stage2. Either way, we can't take any
    // shortcuts here
  }
}       
if(command == ON){
  if(items["FanPin"] == ON &&
     items["FanMode"] == "AUTO" &&
     items["MainSwitch"] == ON &&
     items["FanCtrl"] == ON)
    ok = false;
}     
(ok);

if(items["SystemType"] == "US" && 
   items["CoolingPin"] == ON && 
   event.itemCommand == ON) {
  var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
  load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

  logWarn("heating", "Heating has been commanded ON but Cooling is ON! Turning off the Cooling!");
  events.sendCommand("CoolingCtrl", OFF);
  waitForUpdateState("CoolingPin", OFF, 10);
}


(true);

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/defaults.js');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

var logName = "heating";

logInfo(logName, "Turning " + command + " the heater: curr temp = " + items["MyTemp"] +
                 " setpoint = " + items["MinTempSetpoint"] +
                 " mode = " + items["HeatingMode"]); 

var fanPin = PIN_MAP.get(items["SystemType"]+"_FanPin");
var changed_state = false;

var deferredStage2or3 = function(){
  // It's later now, still too cold? If so, turn on 2nd/3rd stage heating
  logInfo(logName, "it's later; HeatingPin = " + items["HeatingPin"]);
  logInfo(logName, "temp = " + items["MyTempProxy"] +
                   "; stage 2 delta = " + items["Heating2Delta"] +
                   "; minTemp = " + items["MinTempSetpoint"]);
  // If the heat is still enabled, and the temp is still too low...
  if(items["HeatingPin"] == ON &&
     items["MyTempProxy"].floatValue() + items["Heating2Delta"].floatValue() < items["MinTempSetpoint"].floatValue()) {
    logInfo(logName, "Turning on second stage heating");
    if(items["SystemType"] == "HP") {
      // Heat pumps are special
      commandIfDifferent("Stage2Pin", ON);
      commandIfDifferent("Heating2Pin", ON);
      var coolingPin = PIN_MAP.get(items["SystemType"]+"_CoolingPin");
      commandIfDifferent(coolingPin + "off", ON); // Make sure we're still not cooling!
      var stage2Pin = PIN_MAP.get(items["SystemType"]+"_Stage2Pin");
      logInfo(logName, "Turning on " + stage2Pin + "on now.");
      commandIfDifferent(stage2Pin + "on", ON);   // Turn on the second stage

      if(items["Heating3"] == ON) {  // if stage3 heating is enabled
        // also check to see if we should turn on the third stage heat
        if(items["MyTempProxy"].floatValue() +
           items["Heating2Delta"].floatValue() +
           items["Heating3Delta"].floatValue() < minTempSetpoint) {
          var stage3Pin = PIN_MAP.get(items["SystemType"]+"_EHeatPin");
          logInfo(logName, "Turning on " + stage3Pin + "on now.");
          commandIfDifferent("Heating3Pin", ON);
          commandIfDifferent(stage3Pin + "on", ON);   // Turn on the third stage
          events.sendCommand("HeatingMode", items["HeatingMode"]); // Update the LCD if necessary
        }
      }
    } else {
      logInfo(logName, "Turning on " + heatingPin2 + "on now.");
      commandIfDifferent("Heating2Pin", ON);
      // Command for newer kernels
      var heatingPin2 = PIN_MAP.get(items["SystemType"]+"_Heating2Pin");
      commandIfDifferent(heatingPin2 + "on", ON);
    }
  }
}

var heating3Off = function(){
  // only heat pumps have a stage 3
  if(items["SystemType"] == "HP") {
    if(items["Heating3Pin"] != OFF){
      logInfo(logName, "Turning off third stage heating (e-heat)");
      commandIfDifferent("Heating3Pin", OFF);
      var stage3Pin = PIN_MAP.get(items["SystemType"]+"_EHeatPin");
      commandIfDifferent(stage3Pin + "off", ON);
      return true;  // it was not off, we turned it off
    }
  }
  return false;
};

var heating2Off = function(){
  var changed = false;
  if(items["Heating2Pin"] != OFF){
    logInfo(logName, "Ensuring second stage heating is turned off");
    changed = items["Heating2Pin"] != OFF;
    commandIfDifferent("Heating2Pin", OFF);
    if(items["SystemType"] == "HP") { 
      commandIfDifferent("Stage2Pin", OFF);
      var stage2Pin = PIN_MAP.get(items["SystemType"]+"_Stage2Pin");
      commandIfDifferent(stage2Pin + "off", ON);
    } else {
      var heating2Pin = PIN_MAP.get(items["SystemType"]+"_Heating2Pin");
      commandIfDifferent(heating2Pin + "off", ON);
    }
  } 
  // make sure stage3 is always turned off if we are turning off stage 2
  return heating3Off() || changed;
};

// Turns ON/OFF heating and the Fan (if US type) if it isn't already
if(command == ON) {
  commandIfDifferent("MainSwitch", ON);

  // Also turn on the Fan if US or HP mode
  if(items["SystemType"] == "US" || items["SystemType"] == "HP") {
    commandIfDifferent("FanCtrl", OFF);
  }

  // Turn on the heat
  changed_state = changed_state || items["HeatingPin"] != ON;
  commandIfDifferent("HeatingPin", ON);
  if(items["SystemType"] == "HP") {
    // For heat pumps we need to make sure the cooling pin is off, and stage1 is on
    var coolingPin = PIN_MAP.get(items["SystemType"]+"_CoolingPin");
    var stage1Pin = PIN_MAP.get(items["SystemType"]+"_Stage1Pin");
    logInfo(logName, "Heat Pump - Turning off " + coolingPin + "; turning on "+stage1Pin);
    commandIfDifferent(coolingPin + "off", ON);
    commandIfDifferent(stage1Pin + "on", ON);
    if(items["FanMode"] == "Boost") {
      // If the fan is currently boosting, let it continue doing so
      // but have it return to AUTO when done boosting
      events.postUpdate("FanPrevMode", "AUTO");
    } else {
      // If it's not boosting, set it to AUTO
      commandIfDifferent("FanMode", "AUTO");
    }
    commandIfDifferent(fanPin + "on", ON);
  } else if(items["SystemType"] == "US") {
    var heatingPin = PIN_MAP.get(items["SystemType"]+"_HeatingPin");
    commandIfDifferent(heatingPin + "on", ON);
    if(items["FanMode"] == "Boost") {
      // If the fan is currently boosting, let it continue doing so
      // but have it return to AUTO when done boosting
      events.postUpdate("FanPrevMode", "AUTO");
    } else {
      // If it's not boosting, set it to AUTO
      commandIfDifferent("FanMode", "AUTO");
    }
    commandIfDifferent(fanPin + "on", ON);
  } else {
    var heatingPin = PIN_MAP.get(items["SystemType"]+"_HeatingPin");
    logInfo(logName, "Commanding " + heatingPin + "on to ON");
    commandIfDifferent(heatingPin + "on", ON);
  }
  // Additional stages of heating
  if(items["Heating2"] == ON) {
    logInfo(logName, "Multi-stage heating is enabled, checking to see if it should be active");
    var currentTemp = items["MyTempProxy"].floatValue();
    var heating2Delta = items["Heating2Delta"].floatValue();
    var minTempSetpoint = items["MinTempSetpoint"].floatValue();
    var heating2calling = (currentTemp + heating2Delta < minTempSetpoint)
    logInfo(logName, "temp = " + currentTemp +
                     "; stage 2 delta = " + heating2Delta +
                     "; minTemp = " + minTempSetpoint);
    logInfo(logName, "heating2calling = " + heating2calling);

    // Turn off additional stages if appropriate
    if(items["Heating3"] == ON) {  // if stage3 heating is enabled
      var heating3Delta = items["Heating3Delta"].floatValue();
      var heating3calling = items["Heating3"] == ON && (currentTemp + heating2Delta + heating3Delta < minTempSetpoint);
      logInfo(logName, "temp = " + currentTemp +
                       "; Heating3 = " + items["Heating3"] +
                       "; stage 2 delta = " + heating2Delta +
                       "; stage 3 delta = " + heating3Delta +
                       "; minTemp = " + minTempSetpoint +
                       "; heating3calling = " + heating3calling);
      if(!heating3calling) {
        logInfo(logName, "It's too warm for stage 3 (" + items["Heating3"] + "), turn off the third stage heating");
        if(!heating2calling){
          // It's also too warm for stage 2, turn off the second (and third) stage heating
          changed_state = heating2Off() || changed_state;
        } else {
          logInfo(logName, "It's only too warm for stage 3 (" + items["Heating3"] + "), only turn off stage 3");
          changed_state = heating3Off() || changed_state;
        }
      }
    } else { // 3rd stage heating is disabled
      logInfo(logName, "Stage 3 heating is disabling. Turning it off");
      changed_state = heating3Off() || changed_state;
    }
    if(!heating2calling){
      // It's too warm for stage 2, turn off the second (and third) stage heating
      changed_state = heating2Off() || changed_state;
    }

    // if stage2 or stage3 is calling and not already on, turn it on (after a delay)
    heating3calling = items["Heating3"] == ON && (currentTemp + heating2Delta + heating3Delta < minTempSetpoint);
    if((heating2calling && items["Heating2Pin"] != ON) || (heating3calling && items["Heating3Pin"] != ON)) {
      var heat2StartMins = items["Heating2Time"].intValue();
      logInfo(logName, "Scheduling additional stages of heating to start in " + heat2StartMins + " minutes.");
      createTimerSecs(heat2StartMins*60+3, deferredStage2or3);
      // The +3 is to avoid a race condition where the callback can fire before
      // the HeatingPin is turned on (when the delay is set to 0)
    }
  } else { // command == OFF
    changed_state = heating2Off() || changed_state;
  }
} else {
  // Do not turn off heat pumps if cooling is active (as it'd turn off stage1)
  if(items["SystemType"] != "HP" || items["CoolingPin"] != ON) {
    changed_state = heating2Off() || changed_state; // if stage 1 is off, stage 2 should also be off
    changed_state = changed_state || items["HeatingPin"] != OFF;
    commandIfDifferent("HeatingPin", OFF);
    if(items["SystemType"] == "HP") {
      var stage1Pin = PIN_MAP.get(items["SystemType"]+"_Stage1Pin");
      changed_state = items[stage1Pin + "off"] != ON || changed_state;
      commandIfDifferent(stage1Pin + "off", ON);
    } else {
      var heatingPin = PIN_MAP.get(items["SystemType"]+"_HeatingPin");
      changed_state = items[heatingPin + "off"] != ON || changed_state;
      commandIfDifferent(heatingPin + "off", ON);
    }
    if(items["SystemType"] == "US" || items["SystemType"] == "HP") {
      createTimerSecs(10, restoreFanState);
    }
  }
}
if(changed_state)
  logInfo(logName, "Making sure the LCD is updated with the current state: " + items["HeatingMode"]);
  events.sendCommand("HeatingMode", items["HeatingMode"]);

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

var ok = (newState == "US" || newState == "EU" || newState == "HP");
if(!ok){
  logWarn("systemtype", newState + " is not a valid state, reverting to " + oldState);
  var restState = (oldState == "US" || oldState == "EU" || oldState == "HP") ? oldState : "EU";
  events.sendCommand("SystemType", restState); // executes the script to update the file
}
else if(oldState == NULL || oldState == UNDEF) {
  logWarn("systemtype", "Previous state was " + oldState + " ignoring change.");
  ok = false;
}
ok;

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');
load(OPENHAB_CONF + '/automation/lib/hestia/defaults.js');

var logName = "systemtype";

// Turn everything OFF
events.sendCommand("MainSwitch", OFF);

// Waiting for all the modes to turn OFF
var notOff = function(i) { return items[i.name] != "OFF"; }
while(ir.getItem("Modes").members.stream().filter(notOff).count() > 0) {
  logInfo(logName, "Waiting for everything to become OFF.");
  sleep(1);
}

// Reset the setpoints
var tempUnit = items["TempUnit"];
var comfMode = items["Comfort_Mode"];
events.sendCommand("MinTempSetpoint", DEFAULTS.get(tempUnit+"_MIN_DEF"));
events.sendCommand("MaxTempSetpoint", DEFAULTS.get(tempUnit+"_MAX_DEF"));
events.sendCommand("HumiSetpoint", DEFAULTS.get("Humi_DEF"));
events.sendCommand("Heating3", "OFF");
events.sendCommand("Heating3Delta", "1");

// Executing the sed to update the systemtype file is now done by
// the Exec binding when the SystemType Item received the command
// to change.
logInfo(logName, "Rebooting...");
sleep(20); // give everything time to settle down
events.sendCommand("RebootButton", ON);
logInfo(logName, "Done");

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

var ok = true
if(event.itemName == "FanPin"){
  logInfo("pins", "FanPin commanded to " + newState);
  if(items["SystemType"] == "US" &&
     (items["HeatingPin"] == ON || items["CoolingPin"] == ON) &&
     newState == OFF){
    logWarn("pins", "Cannot turn off the fan when heating or cooling in US system type! Restoring fan states!");
    commandIfDifferent("FanMode", "AUTO");
    commandIfDifferent("FanCtrl", "OFF");
    events.sendCommand("FanPin", ON);
    ok = false;
  }
}
(ok);

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/defaults.js');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

var key = items["SystemType"]+"_"+event.itemName;
// The HeatingPin and Heating2Pin are not in the Heat Pump mode, but the items
// still need to change state to get the UI to react properly. At the same time
// we can't remove them from the list of triggers because they're vital for
// when operating in other modes. So we
if(items["SystemType"] != "HP" || key == "HeatingPin" || key == "Heating2Pin") {
  var pinItem = PIN_MAP.get(key); // checking the key is not null was done in the conditions clause
  logInfo("pins", "Commanding " + pinItem + " to " + newState + " for " + event.itemName);
  events.sendCommand(pinItem, newState);
}

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

var logName = "restore";

//if(items["BackupTimestampResults"] == NULL || items["BackupTimestampResults"] == UNDEF){
//  logInfo(logName, "Checking backup timestamp");
//  events.sendCommand("BackupTimestampCommand", ON);
//  waitForUpdate("BackupTimestampCommand", 5);
//}
//
var ts = items["BackupTimestampResults"];
if(ts == NULL || ts == UNDEF || ts == ""){
  logInfo(logName, "Timestamp isn't set, calling script to get latest");
  var ts = executeCommandLine("/home/pi/scripts/getbackuptimestamp.sh", 5000);
  events.postUpdate("BackupTimestampResults", ts);
}

logInfo(logName, "Timestamp obtained: " + ts);

if(ts == "No backup found.") {
  logger.warn("There is no backup file!");
  events.postUpdate("RestoreButton", "No backup found.");
}

(ts != "No backup found." && ts != NULL && ts != UNDEF);

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

logInfo("restore", "Restoring from /home/pi/scripts/backup.zip");
events.postUpdate("RestoreButton", "Restoring & restarting twice...");
events.sendCommand("RestoreCommand", ON);

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/defaults.js');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

var turnedOn = false;
var key = items["SystemType"]+"_FanPin";
var pinItem = PIN_MAP.get(key);

logInfo("fan", "Turning " + command + " the fan: fan mode = " + items["FanMode"]);
events.sendCommand("FanPin", command);
// for newer kernels which break the old GPIO binding
if(command == ON) {
  logInfo("fan", "setting " + pinItem + "on now");
  events.sendCommand(pinItem + "on", ON);
} else if(command == OFF) {
  logInfo("fan", "setting " + pinItem + "off now");
  events.sendCommand(pinItem + "off", ON);
} else {
  logInfo("fan", "Unknown command issued: " + command);
}

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');
load(OPENHAB_CONF + '/automation/lib/hestia/defaults.js');

var logName = "initialization";

// Set the flag to indicate initialization is in progress
events.postUpdate("Initialized", OFF);

logInfo(logName, "Initializing settings...");

var initFromScript = function(i){
  // This shouldn't be possible, the Exec binding should have
  // called the script already. But we will try to kick it off
  // again here.
  if(items[i] == NULL || items[i] == UNDEF){
    logInfo(logName, i + " is undefined, initializing from script " + cmd);
    events.sendCommand("Get"+i, ON);
    waitForUpdate(i, 5);
  }
  else {
    logDebug(logName, i + " is " + items[i]);
    events.sendCommand(i, items[i]);
  }
}

var initState = function(i, st) {
  if(items[i] == NULL || items[i] == UNDEF){
    logInfo(logName, i + " is undefined, initializing to " + st);
    events.sendCommand(i, st);
  }
  else {
    logDebug(logName, i + " is " + items[i]);
    events.sendCommand(i, items[i]);
  }
}

var initSetpoint = function(i, value, max, min) {
  if(items[i] == NULL || items[i] == UNDEF || 
     items[i].floatValue() > max || items[i].floatValue() < min){
    logInfo(logName, i + " is " + items[i] + ", initializing to " + value);
    events.sendCommand(i, value);
  }
  else {
    logDebug(i + " is " + items[i]);
    events.sendCommand(i, items[i]);
  }
}

// Initialize type Items first
initFromScript("SystemType");
initFromScript("TempUnit");
initFromScript("HumidityType");

// Get the current temp reading
events.sendCommand("GetTemp", ON);

// Initialize the mode Items
initState("FanMode", "OFF");
initState("MainSwitch", "OFF");
initState("HeatingMode", "OFF");
initState("CoolingMode", "OFF");
initState("HotWaterMode", "OFF");
initState("HumidityMode", "OFF");
initState("Heating2", "OFF");
initState("Comfort_Mode", "COMFORT");


// Initialize setpoint Items
var unit = items["TempUnit"];
var min = DEFAULTS.get(unit+"_MIN");
var max = DEFAULTS.get(unit+"_MAX");
var minDef = DEFAULTS.get(unit+"_MIN_DEF");
var maxDef = DEFAULTS.get(unit+"_MAX_DEF");
initSetpoint("MinTempSetpoint", minDef, max, min);
initSetpoint("MinTempSetpoint"+unit, minDef, max, min);
initSetpoint("MaxTempSetpoint", maxDef, max, min);
initSetpoint("MaxTempSetpoint"+unit, maxDef, max, min);

if(items["Comfort_Mode"].class == UnDefType.class){
  logWarn(logName, "Waiting for Comfort_Mode to update");
  waitForUpdate("Comfort_Mode", 10);
  logWarn(logName, "Comfort_Mode finally updated to " + items["Comfort_Mode"]);
}
var comfMode = items["Comfort_Mode"];
var comfDef = DEFAULTS.get(unit+"_"+comfMode+"_DEF");
logInfo(logName, "Comfort_Mode is " + comfMode + ", Default value is " + comfDef);
initSetpoint("Comfort_Value", comfDef, max, min);

def = DEFAULTS.get("Humi_DEF");
min = DEFAULTS.get("Humi_MIN");
max = DEFAULTS.get("Humi_MAX");
initSetpoint("HumiSetpoint", 50, 100, 0);

// Initialize misc settings
initState("HeatingBoostTime", DEFAULTS.get("HeatingBoostTime"));
initState("HotWaterBoostTime",DEFAULTS.get("HotWaterBoostTime"));
initState("HumidityBoostTime", DEFAULTS.get("HumidityBoostTime"));
initState("CoolingBoostTime", DEFAULTS.get("CoolingBoostTime"));
initState("FanBoostTime", DEFAULTS.get("FanBoostTime"));
initState("PreviousTempReading", 0);
initState("PreviousHumiReading", 0);
initState("PreviousPressureReading", 0);
initState("Heating2Time", DEFAULTS.get("Heating2Time"));
initState("Heating2Delta", DEFAULTS.get("Heating2Delta"));
initState("FanCtrl", ON);

// Let the Exec binding init the network and system info Items

// We are initialized enough to operate, set the flag
events.postUpdate("Initialized", ON);
logInfo(logName, "System is ready to operate, kicking off restored behaviors");

// Update PrevMode Items and cancel Boosts
logDebug(logName, "Updating PrevModes");
for each(var i in ir.getItem("Modes").members){
  if(items[i.name] != "Boost"){
    var prevName = i.name.replace("Mode", "PrevMode");
    logDebug(logName, i.name + " is " + items[i.name] + ", updating " + prevName + " to " + items[i.name]);
    events.postUpdate(prevName, items[i.name]);
  }
  else {
    var prev = items[i.name.replace("Mode", "PrevMode")]
    var resetVal = (prev != NULL && prev != UNDEF)? prev : "OFF";
    logInfo(logName, "Cancelling Boost mode for " + i.name + ", restoring to " + resetVal);
    events.sendCommand(i.name, resetVal);
  }
}

// Sometimes the timing works out that MyTemp is updated before the
// rule that synchronizes it with the proxy Items is loaded, leaving 
// the temp proxy Items NULL until the temp changes enough to register.
//if(items["MyTempProxy"] == NULL || items["MyTempProxy"+items["TempUnit"]] == NULL) {
//  logDebug(logName, "MyTempProxy is not set, initializing it with MyTemp.");
//  events.sendCommand("MyTempProxy", items["MyTemp"]);
//}

// Sometimes the timing works out that MyTemp is updated before the
// rule that synchronizes it with the proxy Items is loaded, leaving
// the temp proxy Items NULL until the next large temperature change. 
// The timing might also work where the temp is read before the LCD is
// ready to receive it. So we resend the current reading so everything 
// gets in sync.
events.sendCommand("MyTempProxy", items["MyTemp"]);

events.postUpdate("Initialized", ON); // Allow changes to run

logDebug(logName, "Triggering devices");
// Do the fan mode first so screen ends up at Heating or Cooling
// if either are on
if((items["SystemType"] == "US" || items["SystemType"] == "HP") && items["FanMode"] != "OFF"){
  events.sendCommand("FanMode", ON);
}

if(items["HeatingMode"] != "OFF") events.sendCommand("HeatingCheck", ON);

if(items["SystemType"] == "EU"){
  if(items["HotWaterMode"] != "OFF") events.sendCommand("HotWaterCheck", ON);
  if(items["HumidityMode"] != "OFF") events.sendCommand("HumidityCheck", ON);
}

// Heating and cooling are handled by the same rule. We only need
// to command CoolingMode if it wasn't already triggered by HeatingMode.
if(items["CoolingMode"] != "OFF") events.sendCommand("CoolingCheck", ON);

events.sendCommand("GitInstalledVersionCommand", "ON");

logDebug(logName, "Done initializing settings");

var OPENHAB_CONF = Java.type('java.lang.System').getenv('OPENHAB_CONF');
load(OPENHAB_CONF + '/automation/lib/hestia/utils.js');

var device = event.itemName.replace("Mode", "");
logInfo("mode", device + " mode changed from " + oldState + " to " + newState);

// Update PrevMode
