    // items["Heating2"] tells us whether the second stage is enabled.
    // it was named when there was only 2-stage heating, no 2-stage cooling
    if(items["Heating2"] == ON) {
      logInfo("cooling", "Second stage cooling");
      var stage2StartMins = items["Heating2Time"].intValue(); // stage2 delay

      // If it's already cool enough right now, turn off stage 2
      if(items["MyTempProxy"].floatValue() < items["MaxTempSetpoint"].floatValue() + items["Heating2Delta"].floatValue()) {
        createTimerSecs(10, function(){
          commandIfDifferent(stage2Pin + "off", ON);
