        });
      } else {
        // We're calling for stage2, call this function after the user-configured delay
        logInfo("cooling", "Scheduling second stage cooling to start in " + stage2StartMins + " minutes.");
        createTimerSecs(stage2StartMins*60, function(){
          // It's later, is it still too hot? If so, turn on 2nd stage cooling
          if(items["MyTempProxy"].floatValue() > items["MaxTempSetpoint"].floatValue() + items["Heating2Delta"].floatValue()) {
            // we're only using sendCommand because HP is only supported on Debian 12+
